'use strict';
const D=OWL_DATA,E=OWL_ENGINE,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({field:'Computer Science',role:'graduate',interests:['Technology','Design','Research'],goal:'create',offer:'Technology',seek:'Design',saved:[],plan:[],shortlist:[],notes:{},local:[],visibility:true,diverse:true,budget:180,planMode:'all',planTime:'any',planFree:false,buffer:15});
let state=initial();try{const raw=JSON.parse(localStorage.getItem('owlcircle-v2'));if(raw&&typeof raw==='object'){for(const k of ['field','role','goal','offer','seek','visibility','diverse','budget','planMode','planTime','planFree','buffer'])if(typeof raw[k]===typeof state[k])state[k]=raw[k];for(const k of ['saved','plan','shortlist'])if(Array.isArray(raw[k]))state[k]=raw[k].filter(x=>typeof x==='string');if(Array.isArray(raw.interests))state.interests=raw.interests.filter(t=>D.topics.includes(t));if(raw.notes&&typeof raw.notes==='object'&&!Array.isArray(raw.notes))state.notes=raw.notes;if(Array.isArray(raw.local))state.local=raw.local.filter(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&/^\d{2}:\d{2}$/.test(e.start)&&/^\d{2}:\d{2}$/.test(e.end)&&Array.isArray(e.topics)&&Array.isArray(e.goals)&&E.validURL(e.url)).map(e=>({...e,status:'local'}));}}catch{}
if(!D.fields[state.field])state.field='Exploring';if(!D.goals[state.goal])state.goal='create';
let view=['discover','plan','people','sources','about'].includes(location.hash.slice(1))?location.hash.slice(1):'discover';
let filters={query:'',source:'all',kind:'all',category:'all',format:'all',day:'all',sort:'match'},peopleFilter='all',resourceQuery='',resourceCategory='all',tourStep=0,draftInterests=[],lastFocus=null;
const source=id=>D.sources.find(s=>s.id===id)||{id:'local',name:'Your local import',short:'Local import',url:'',status:'Unverified local entry'};
const allEvents=()=>[...D.events,...state.local];const event=id=>allEvents().find(e=>e.id===id);
const profile=()=>({...state,fieldTopics:D.fields[state.field]||[]});
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const weekday=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'});
function time(t){let [h,m]=t.split(':').map(Number);return `${h%12||12}${m?':'+String(m).padStart(2,'0'):''}${h<12?'am':'pm'}`}
const range=e=>`${time(e.start)}–${time(e.end)} ET`;
const kindLabel=e=>e.status==='public'?'Public listing':e.status==='demo'?'Simulated event':'Local · unverified';
const badge=e=>`<span class="tag ${e.status}">${kindLabel(e)}</span>`;
function persist(){try{localStorage.setItem('owlcircle-v2',JSON.stringify(state))}catch{toast('Storage unavailable. Your changes will last for this visit.')}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(window.owlToast);window.owlToast=setTimeout(()=>$('#toast').classList.add('hidden'),3700)}
function eligible(e){return !e.eligibility||state.role==='all'||(e.eligibility==='instructor'&&state.role==='instructor')||(e.eligibility==='undergraduate'&&state.role==='undergraduate')}
function rankedList(){let items=allEvents().filter(e=>eligible(e)&&(filters.source==='all'||e.sources.includes(filters.source))&&(filters.kind==='all'||e.status===filters.kind)&&(filters.category==='all'||e.category===filters.category)&&(filters.format==='all'||e.format===filters.format)&&(filters.day==='all'||e.date===filters.day));const known=E.classify(filters.query);if(filters.query&&!known.length){const q=filters.query.toLowerCase();items=items.filter(e=>[e.title,e.description,e.place,...e.topics].join(' ').toLowerCase().includes(q))}items.sort(filters.sort==='date'?(a,b)=>(a.date+a.start).localeCompare(b.date+b.start):(a,b)=>E.rank(b,profile(),filters.query,state.diverse).score-E.rank(a,profile(),filters.query,state.diverse).score||(a.date+a.start).localeCompare(b.date+b.start));return items}
function reason(e){const r=E.rank(e,profile(),filters.query,state.diverse),text=[];if(r.intent&&e.goals.includes(r.intent))text.push('Fits “'+D.goals[r.intent].toLowerCase()+'”');else if(r.matchedGoal)text.push('Supports your goal');if(r.shared.length)text.push(r.shared.slice(0,2).join(' + '));if(r.outside&&state.diverse)text.push('Outside your usual field');return text.slice(0,2).join(' · ')||'A chance to explore a different interest'}
function card(e){return `<article class="event-card"><div class="card-cover ${esc(e.category)}"><div class="date-square"><b>${Number(e.date.slice(-2))}</b>${weekday(e.date)} · NOV</div><button class="icon-button bookmark ${state.saved.includes(e.id)?'saved':''}" data-save="${esc(e.id)}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}" aria-pressed="${state.saved.includes(e.id)}">${state.saved.includes(e.id)?'✓':'+'}</button></div><div class="card-content"><div class="source-line"><span>${esc(source(e.source).short)}${e.sources.length>1?' +'+(e.sources.length-1):''}</span>${badge(e)}</div><button class="card-title" data-event="${esc(e.id)}">${esc(e.title)}</button><div class="card-meta">◷ <span>${range(e)}</span></div><div class="card-meta">⌖ <span>${esc(e.place)}</span></div><p class="card-description">${esc(e.description.length>108?e.description.slice(0,105)+'…':e.description)}</p><div class="card-bottom"><div class="card-tags"><span class="tag">${esc(e.category)}</span><span class="tag">${e.price===0?'Free':e.price?'$'+e.price:'Cost not listed'}</span>${e.beginner?'<span class="tag">Beginner friendly</span>':''}</div><div class="reason">✦ ${esc(reason(e))}</div>${e.sourceNote?'<p class="source-evidence attention">Source descriptions differ · review details</p>':''}<div class="card-buttons"><button class="text-button" data-event="${esc(e.id)}">Details ↗</button><button class="button plan-button ${state.plan.includes(e.id)?'quiet':''}" data-plan="${esc(e.id)}">${state.plan.includes(e.id)?'✓ In plan':'+ Add to plan'}</button></div></div></div></article>`}
function select(id,label,options,value){return `<select id="${id}" aria-label="${label}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`}
function discover(){const items=rankedList(),inferred=E.classify(filters.query);return `<section class="hero"><div class="hero-copy"><span class="eyebrow">One campus. A wider circle.</span><h1>Find your opportunity.<br>Then find <em>your people.</em></h1><p>Campus events, academic support, career resources, and student communities—one starting point for what you want to do next.</p></div><div class="hero-art" aria-hidden="true"><span class="orbit-label a">Libraries ↗</span><span class="orbit-label b">Clubs & community</span><span class="orbit-label c">Careers & ideas</span><span class="orbit-label d">Arts & research</span><div class="orbit-center"><span class="eyebrow">Your campus, connected</span><strong>A new skill.<br>An unexpected connection.</strong><span class="tag pill">◎ Start with curiosity</span></div></div></section><div class="intro-line"><div class="data-notice"><span class="tag public">9 public snapshots</span><span class="tag demo">12 simulated events</span><span>Nov 9–15, 2026 · No live sync</span></div><button class="text-button" data-nav="sources">See sources ↗</button></div><form id="goal-form" class="search-panel"><div class="heading-row"><label for="goal-query">What would you like to do next?</label><button type="button" class="tag text-button" data-action="model">✦ Local AI intent matching</button></div><div class="goal-search"><input id="goal-query" maxlength="250" value="${esc(filters.query)}" placeholder="I want to build a project with someone from another major…" autocomplete="off"><button class="button primary" type="submit">Find my opportunities <span>↗</span></button></div><div class="prompts"><span>TRY A GOAL</span><button type="button" class="prompt" data-prompt="Build an app with a designer">Build a project</button><button type="button" class="prompt" data-prompt="I am new here and want to make friends">Meet new people</button><button type="button" class="prompt" data-prompt="Learn how to analyze research data">Explore research</button><button type="button" class="prompt" data-prompt="Volunteer and give back to my community">Give back</button></div>${filters.query?`<div class="query-result"><span>✦</span>${inferred.length?`<span>Inferred focus: <b>${esc(D.goals[inferred[0].label])}</b>. Results ranked across sources.</span>`:'<span>No learned intent recognized. Showing matching text.</span>'}<button type="button" class="text-button" data-action="clear-query">Clear</button></div>`:''}</form>${filters.query?`<section class="related-resources"><div class="section-heading"><div><h3>Resources for your next step</h3><p class="tiny">Suggested from curated tags and your inferred goal.</p></div><button class="text-button" data-nav="sources">Browse all resources ↗</button></div><div class="resource-grid compact">${matchingResources(filters.query).slice(0,3).map(resourceCard).join('')}</div></section>`:''}<div class="section-heading"><div><h2>${filters.query?'Opportunities for your goal':'A little closer to your next thing'}</h2><small>${items.length} results · tailored to your interests and audience</small></div><div class="actions"><button class="button small-button" data-action="profile">Edit interests</button><button class="button dark small-button" data-nav="plan">Build my plan ↗</button></div></div><div class="filters">${select('filter-kind','Data type',[['all','All listings'],['public','Public listings only'],['demo','Simulated events only'],['local','My local imports']],filters.kind)}${select('filter-source','Event source',[['all','All sources'],...D.sources.map(s=>[s.id,s.short])],filters.source)}${select('filter-category','Event category',[['all','All topics'],...[...new Set(allEvents().map(e=>e.category))].sort().map(c=>[c,c])],filters.category)}${select('filter-format','Event format',[['all','Any format'],['Online','Online'],['In person','In person']],filters.format)}${select('filter-day','Event date',[['all','Any day'],...[...new Set(allEvents().map(e=>e.date))].sort().map(d=>[d,weekday(d)+' '+shortDate(d)])],filters.day)}${select('filter-sort','Sort events',[['match','Best fit'],['date','Soonest first']],filters.sort)}<label class="toggle-label"><input id="diversify" type="checkbox" ${state.diverse?'checked':''}>Explore beyond my field</label></div><div class="card-grid">${items.length?items.map(card).join(''):`<div class="empty"><h3>No opportunities match these filters.</h3><p>Try a different goal, broaden your filters, or change your audience in Edit interests.</p><button class="button" data-action="clear-filters">Reset filters</button></div>`}</div><p class="tiny" style="margin-top:20px">Public listings are manually curated snapshots checked November 5, 2026, not real-time availability. Open the source before registering. Simulated events are fictional and cannot be attended.</p>`}
function planConflicts(){const list=state.plan.map(event).filter(Boolean),pairs=[];for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++)if(E.conflicts(list[i],list[j],state.buffer))pairs.push([list[i],list[j]]);return pairs}
function planView(){const list=state.plan.map(event).filter(Boolean).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),saved=state.saved.map(event).filter(Boolean),total=list.reduce((n,e)=>n+E.duration(e),0),pairs=planConflicts();return `<div class="page-heading"><div><span class="eyebrow">From discovery to doing</span><h1>A week that works for you.</h1><p class="lead">Build a small, varied plan across campus. Save the possibilities. Make time for the ones that matter.</p></div><button class="button" data-action="export" ${list.length?'':'disabled'}>↓ Export calendar</button></div><div class="plan-layout"><div><section class="panel"><h3>Make a plan around your goal</h3><p class="tiny">Up to 3 events, with a 15-minute gap between sessions. The planner favors a mix of sources and topics. Times are Eastern.</p><div class="planner-controls"><div class="field"><label for="plan-budget">Time budget for the week</label>${select('plan-budget','Weekly time budget',[['120','2 hours'],['180','3 hours'],['300','5 hours'],['480','8 hours']],String(state.budget))}</div><div class="field"><label for="plan-mode">Include</label>${select('plan-mode','Planner data',[['all','Public + simulated'],['public','Public listings only'],['demo','Simulated events only'],['saved','Only my saved events']],state.planMode)}</div><div class="field"><label for="plan-time">Start times</label>${select('plan-time','Planner start times',[['any','Any time'],['afternoon','12pm or later'],['evening','4pm or later']],state.planTime)}</div></div><div class="actions" style="align-items:center;justify-content:space-between"><label class="checkbox-line"><input id="plan-free" type="checkbox" ${state.planFree?'checked':''}>Only explicitly free events</label><button class="button primary" data-action="suggest-plan">${list.length?'Regenerate suggestions':'Suggest my campus plan'} ✦</button></div><p class="tiny">This replaces your current plan, not your saved events. ${filters.query?'Using your goal: “'+esc(filters.query)+'”.':'Using your profile goal: '+esc(D.goals[state.goal])+'.'}</p><div class="plan-summary"><div><strong>${list.length}</strong><span>events in your plan</span></div><div><strong>${Math.round(total/6)/10}h</strong><span>event time</span></div><div><strong>${new Set(list.map(e=>e.source)).size}</strong><span>different sources</span></div></div>${pairs.map(([a,b])=>`<div class="warning-box"><b>Schedule conflict or insufficient travel gap</b><br>${esc(a.title)} overlaps or is within 15 minutes of ${esc(b.title)}. Remove one or regenerate your plan.</div>`).join('')}${total>state.budget?'<div class="warning-box">This plan exceeds your selected time budget. Remove an event or increase the budget.</div>':''}${list.length&&!pairs.length?'<p class="tiny">✓ No overlaps with a 15-minute gap. Check actual travel time and source details before attending.</p>':''}${list.length?list.map(e=>`<article class="plan-item"><div class="plan-time">${weekday(e.date)}<b>${Number(e.date.slice(-2))}</b>November</div><div class="plan-info">${badge(e)}<h3>${esc(e.title)}</h3><p class="tiny">${range(e)} · ${esc(e.place)}<br>${esc(source(e.source).name)}</p><div class="actions"><button class="text-button" data-event="${esc(e.id)}">View details ↗</button>${e.status==='demo'?`<button class="text-button" data-people-event="${e.id}">Find demo peers ↗</button>`:''}<button class="text-button" data-note="${esc(e.id)}">${state.notes[e.id]?'Edit reflection':'Add a private reflection'}</button><button class="text-button" data-remove-plan="${esc(e.id)}">Remove</button></div></div></article>`).join(''):`<div class="plan-empty"><h3>Your campus week starts here.</h3><p class="muted">Get suggestions above or add events from Discover.</p><button class="button" data-nav="discover">Explore opportunities ↗</button></div>`}</section><p class="tiny" style="margin-top:12px">Adding to your plan is not an RSVP. Calendar exports mark fictional events with [DEMO]. Your plan stays in this browser.</p></div><aside class="panel"><h3>Your saved possibilities <span class="tag">${saved.length}</span></h3><p class="tiny">Bookmarks are a shortlist, not a schedule.</p>${saved.length?saved.map(e=>`<div class="saved-mini"><h4>${esc(e.title)}</h4><p>${shortDate(e.date)} · ${range(e)}</p><div class="actions"><button class="text-button" data-plan="${esc(e.id)}">${state.plan.includes(e.id)?'✓ In plan':'+ Add to plan'}</button><button class="text-button" data-save="${esc(e.id)}">Unsave</button></div></div>`).join(''):'<p class="tiny">Use the + in an event’s top corner to save it here.</p>'}</aside></div>`}
function personMatch(p){const active=[...new Set([...state.plan,...state.saved])],shared=p.events.filter(id=>active.includes(id)),interest=p.topics.filter(t=>state.interests.includes(t)),gives=p.offer===state.seek,learns=p.seek===state.offer;return {shared,interest,gives,learns,score:shared.length*5+interest.length*2+(gives?5:0)+(learns?3:0)}}
function peopleView(){const list=state.visibility?D.people.filter(p=>p.optIn&&(peopleFilter==='all'||(peopleFilter==='shortlist'?state.shortlist.includes(p.id):p.events.includes(peopleFilter)))).sort((a,b)=>personMatch(b).score-personMatch(a).score):[];return `<div class="page-heading"><div><span class="eyebrow">An introduction with a reason</span><h1>Different strengths.<br>Shared possibilities.</h1><p class="lead">Find someone who can teach you something—and learn something from you. Start with a shared event.</p></div><button class="button" data-action="profile">Edit skills & interests ↗</button></div><div class="data-notice" style="margin-bottom:20px"><span class="tag demo">All 6 profiles are fictional</span><span>No real attendees, messages, or connection requests.</span></div><div class="filters">${select('people-filter','Filter student matches',[['all','All sample peers'],['shortlist','My local shortlist'],...D.events.filter(e=>e.status==='demo').map(e=>[e.id,e.title])],peopleFilter)}<label class="toggle-label"><input id="visibility" type="checkbox" ${state.visibility?'checked':''}>Enable demo matching</label></div><div class="people-grid">${list.length?list.map(p=>{const m=personMatch(p),short=state.shortlist.includes(p.id);return `<article class="person-card"><div class="person-heading"><span class="avatar ${p.color}">${p.initials}</span><div><h3>${p.name}</h3><span class="tiny">${p.field}</span></div><span class="tag demo">Demo profile</span></div><p>${p.bio}</p><div class="skill-exchange"><div><span>Can share</span><b>${p.offer}</b></div><div><span>Wants to learn</span><b>${p.seek}</b></div></div><div class="reason">✦ ${m.gives?'Can help you learn '+esc(state.seek):m.learns?'Your '+esc(state.offer)+' skills complement their goal':m.interest.length?'Shared interests: '+m.interest.join(', '):'A different perspective to explore'}${m.shared.length?' · '+m.shared.length+' shared saved or planned event'+(m.shared.length>1?'s':''):''}</div><p class="tiny">Sample event: ${esc(event((m.shared[0]||p.events[0])).title)}</p><div class="card-buttons"><button class="text-button" data-intro="${p.id}">Prepare an introduction ↗</button><button class="button small-button" data-shortlist="${p.id}" aria-pressed="${short}">${short?'✓ Shortlisted':'+ Meet later'}</button></div></article>`}).join(''):`<div class="empty"><h3>${state.visibility?'No peers on this list yet.':'You’re in control of your circle.'}</h3><p>${state.visibility?'Shortlist a sample peer or select another event.':'Enable demo matching to explore fictional peer recommendations. Nothing is published about you.'}</p></div>`}</div><p class="tiny" style="margin-top:18px">The demo uses a local profile only. A production network would require verified accounts, explicit opt-in per event, blocking/reporting, and consent before introductions. No attendee information is inferred from public event pages.</p>`}
function resourceCard(r){return `<article class="resource-card"><span class="eyebrow">${esc(r.category)}</span><h3>${esc(r.name)}</h3><small>${esc(r.org)}</small><p>${esc(r.description)}</p><a class="text-button" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open official resource ↗</a></article>`}
function matchingResources(q=''){const terms=E.tokenize(q),intent=E.classify(q)[0]?.label||state.goal;return D.resources.map(r=>{const words=new Set(E.tokenize([r.name,r.description,r.keywords].join(' ')));return {r,score:terms.reduce((n,t)=>n+(words.has(t)?3:0),0)+(r.goals.includes(intent)?2:0)}}).sort((a,b)=>b.score-a.score).map(x=>x.r)}
function resourceDirectory(){const terms=E.tokenize(resourceQuery);const rows=matchingResources(resourceQuery).filter(r=>(resourceCategory==='all'||r.category===resourceCategory)&&(!terms.length||terms.some(t=>E.tokenize([r.name,r.description,r.keywords,r.org].join(' ')).includes(t))));return `<section class="resource-directory"><div class="section-heading"><div><h2>More than events. A place to find support.</h2><p class="tiny">10 official resource links · A curated starting point, not a complete university directory.</p></div></div><form id="resource-form" class="resource-search"><div class="field"><label for="resource-query">What kind of resource do you need?</label><input id="resource-query" value="${esc(resourceQuery)}" placeholder="Try writing, research, food, internships…" maxlength="100"></div><div class="field"><label for="resource-category">Category</label>${select('resource-category','Resource category',[['all','All resources'],...[...new Set(D.resources.map(r=>r.category))].map(c=>[c,c])],resourceCategory)}</div><button class="button primary" type="submit">Find resources ↗</button></form><p class="tiny">${rows.length} resource${rows.length===1?'':'s'} · Descriptions reviewed November 5, 2026. Services and appointments stay with the original provider.</p><div class="resource-grid">${rows.length?rows.map(resourceCard).join(''):'<div class="empty"><h3>No matching resources.</h3><p>Try a broader term or choose All resources.</p><button class="button" data-action="reset-resources">Reset search</button></div>'}</div></section>`}
function sourcesView(){return `<div class="page-heading"><div><span class="eyebrow">One place to begin</span><h1>One campus.<br>One place to start.</h1><p class="lead">Find events, ongoing support, and student communities in one hub. Follow the original source for the next step.</p></div><button class="button primary" data-action="import">+ Bring in an event</button></div>${resourceDirectory()}<div class="section-heading"><div><span class="eyebrow">Where our events come from</span><h2>Connected sources, clear provenance.</h2></div></div><div class="metric-strip"><div><b>6</b><span>source families represented</span></div><div><b>9</b><span>curated public event snapshots</span></div><div><b>2</b><span>cross-listed events consolidated</span></div></div><p class="tiny">Snapshot date: November 5, 2026. These are a selected sample, not complete campus coverage. There are no live feed connections or private Handshake/Owl Connect imports.</p><div class="process"><div><b>01 · Collect</b><p>Public pages or manually pasted event text.</p></div><div><b>02 · Normalize</b><p>A consistent date, time, topic, and source.</p></div><div><b>03 · Review</b><p>Spot duplicates and conflicting information.</p></div><div><b>04 · Discover</b><p>Rank by your goal, then build your plan.</p></div></div><div class="source-grid">${D.sources.map((s,i)=>{const entries=D.events.filter(e=>e.sources.includes(s.id));return `<article class="source-card"><div class="source-line"><span class="eyebrow">${esc(s.kind)}</span><span class="tag ${s.status.includes('Demo')?'demo':'public'}">${s.status}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="source-stats"><span><b>${entries.filter(e=>e.status==='public').length}</b>public snapshots</span><span><b>${entries.filter(e=>e.status==='demo').length}</b>simulated examples</span></div><div class="actions"><button class="text-button" data-source-filter="${s.id}">Explore these listings ↗</button><a class="button small-button" href="${s.url}" target="_blank" rel="noopener noreferrer">Original source ↗</a></div></article>`}).join('')}</div><section class="panel" style="margin-top:22px"><h3>Provenance is part of the product</h3><p class="muted">The ArcGIS session appears on the Libraries site and the GIS Day program. Its time agrees, but the descriptions differ. OwlCircle keeps one event card, retains both links, and flags the discrepancy for a human to resolve.</p><div class="actions"><button class="button" data-event="arcgis">Inspect the source conflict ↗</button><button class="button" data-action="duplicate-demo">Try duplicate detection ↗</button></div></section>`}
function aboutView(){return `<section class="about-hero"><span class="eyebrow">The added value</span><h1>Turn scattered opportunities<br>into <em>a connected campus journey.</em></h1><p>OwlCircle is a discovery and planning layer across existing campus resources. Start with what you want to achieve, build a varied plan, and find a person who complements your interests.</p><div class="actions"><button class="button primary" data-action="tour">Try the 60-second demo ↗</button><button class="button" data-nav="sources">Inspect our sources</button></div></section><div class="about-grid"><div class="panel"><div class="number">01</div><h3>Discover across boundaries</h3><p>A single goal can lead to library expertise, a business workshop, academic support, and a student community. Events and ongoing resources share one starting point.</p></div><div class="panel"><div class="number">02</div><h3>Make discovery actionable</h3><p>A time budget, scheduling checks, varied sources, and calendar export turn an interesting list into a manageable plan.</p></div><div class="panel"><div class="number">03</div><h3>Connect through contribution</h3><p>Match what you can share with what someone wants to learn. Explain the connection and anchor it to a shared event.</p></div></div><section class="panel"><h2>How we fit alongside existing tools</h2><p class="muted">Handshake and Owl Connect already offer valuable discovery and community features. Our claim is the combined cross-source workflow below—not that other platforms lack search, personalization, or networking.</p><div class="compare"><table><thead><tr><th>Resource</th><th>Existing role</th><th>OwlCircle’s proposed contribution</th></tr></thead><tbody><tr><td>Handshake</td><td>Career opportunities, event discovery, professional networking, and registration.</td><td>Connect career events to research, creative, and community opportunities in one goal-based plan.</td></tr><tr><td>Owl Connect</td><td>Student organizations, campus involvement, events, and participation tools.</td><td>Bring involvement opportunities together with other public campus sources and complementary peer interests.</td></tr><tr><td>Temple calendars</td><td>Broad public event listings across schools and departments.</td><td>Keep source provenance, flag conflicting cross-listings, and add personal scheduling and next-step planning.</td></tr></tbody></table></div><div class="citation-links">Research: <a href="https://support.joinhandshake.com/hc/en-us/articles/7653951469207-Discover-Events-Fairs-in-Handshake" target="_blank" rel="noopener noreferrer">Handshake event features ↗</a><a href="https://careercenter.temple.edu/resources/handshake" target="_blank" rel="noopener noreferrer">Temple Career Center ↗</a><a href="https://studentaffairs.temple.edu/student-leadership-engagement/getting-involved/get-involved-owl-connect" target="_blank" rel="noopener noreferrer">Owl Connect ↗</a><a href="https://now.temple.edu/events" target="_blank" rel="noopener noreferrer">Temple calendar ↗</a></div></section><div class="about-detail"><section class="panel"><h3>What the AI actually does</h3><p>A small multinomial Naive Bayes model classifies a typed goal into six intents. It learns word frequencies from 72 synthetic training phrases and runs entirely in the browser. The inferred intent feeds an explainable ranking system.</p><p>Scheduling, duplicate checks, peer matching, and text extraction use deterministic rules. Introduction drafts use templates. There is no hidden language-model API, live crawler, or claim of validated recommendation accuracy.</p><button class="text-button" data-action="model">See the model in action ↗</button></section><section class="panel"><h3>What is real in this prototype</h3><p>Public event snapshots come from researched Temple pages. All simulated listings and student profiles are explicitly marked. Search, learned intent inference, filtering, bookmarks, planning, duplicate detection, local import, calendar export, and private reflections work.</p><p>Accounts, real messaging, live ingestion, event registration, and a shared student database are not implemented. Registration remains on the original platform.</p></section><section class="panel"><h3>A feasible next step</h3><p>Proposed pilot: one department, Libraries, and one consenting student organization over four weeks. Start with permissioned feeds or organizer submissions; review duplicates and updates before publication.</p><p>Planning estimate: 2 student developers at 8–10 hours each per week, one organizer reviewer, and about $0–$50 per month for a small hosted pilot. SSO, data agreements, and any language-model usage would need separate assessment.</p></section><section class="panel"><h3>Measure value and protect people</h3><p>Test time to find a relevant event, discovery outside a student’s home school, plan completion, and voluntary post-event connections. No outcome improvements have been measured yet.</p><p>Use opt-in profiles, clear source links, transparent explanations, keyboard-accessible controls, and human correction. Avoid sensitive-attribute inference. Preferences and reflections stay in this browser; external source links open the original sites.</p></section></div><section class="panel"><span class="eyebrow">AI use declaration</span><h3 style="margin-top:10px">Built with ChatGPT / Codex assistance</h3><p class="muted">Used for research synthesis, interface and code generation, synthetic examples and training phrases, matching design, test development, and presentation wording. No external generative AI API is used at runtime. The exact assistant model version is not asserted.</p><p class="tiny">Team 28 · Temple AI Build · Independent student prototype, not an official Temple service.</p></section>`}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));$('#plan-count').textContent=state.plan.filter(id=>event(id)).length;$('#profile-summary').textContent=state.field;$('#breadcrumb').textContent='Campus / '+{discover:'Discover',plan:'My plan',people:'Find your people',sources:'Campus resources',about:'Why OwlCircle'}[view];$('#main').innerHTML=({discover,plan:planView,people:peopleView,sources:sourcesView,about:aboutView}[view])();document.title='OwlCircle · '+{discover:'Discover your campus',plan:'My campus plan',people:'Find your people',sources:'Campus resources',about:'Why OwlCircle'}[view]}
function navigate(to){if(!['discover','plan','people','sources','about'].includes(to))return;view=to;if(location.hash!=='#'+to)history.replaceState(null,'','#'+to);render();window.scrollTo(0,0)}
function show(title,html,kicker='OwlCircle'){lastFocus=document.activeElement;$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=`<h2 id="modal-title">${esc(title)}</h2>`+html;if(!$('#modal').open)$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close();if(lastFocus?.isConnected)lastFocus.focus()}
function details(id){const e=event(id);if(!e)return;const src=source(e.source);show(e.title,`<div class="actions">${badge(e)}<span class="tag">${esc(e.category)}</span></div><div class="detail-facts"><div><b>When</b><span>${weekday(e.date)}, ${shortDate(e.date)}, 2026<br>${range(e)}</span></div><div><b>Where</b><span>${esc(e.place)}</span></div><div><b>Who it is for</b><span>${esc(e.audience)}</span></div><div><b>Cost</b><span>${e.price===0?'Free':e.price?'$'+e.price:'Not stated in the source'}</span></div></div><p class="detail-desc">${esc(e.description)}</p><div class="reason">✦ ${esc(reason(e))}</div>${e.sourceNote?`<div class="warning-box"><b>Source check needed</b><br>${esc(e.sourceNote)}</div>`:''}<div class="detail-provenance"><p><b>${e.status==='public'?'Public source snapshot · checked November 5, 2026':e.status==='demo'?'Fictional event for demonstration':'Locally entered event · not verified'}</b></p><p>${e.status==='public'?'Details were manually curated from public pages, not synchronized. Confirm current time, eligibility, and availability before attending.':e.status==='demo'?'The title, schedule, and location are invented. The source link shows the type of campus resource represented; it is not a registration page for this event.':'You added this entry to this browser. It has not been checked by OwlCircle or the organizer.'}</p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${e.status==='public'?'View original listing / registration':'Visit source website'} ↗</a>${e.alternateUrl?` · <a href="${esc(e.alternateUrl)}" target="_blank" rel="noopener noreferrer">Second source ↗</a>`:''}<p style="margin:10px 0 0">Accessibility: ${esc(e.access)}</p></div><div class="modal-bottom"><button class="button" data-save="${esc(e.id)}">${state.saved.includes(e.id)?'✓ Saved':'+ Save event'}</button><button class="button primary" data-plan="${esc(e.id)}">${state.plan.includes(e.id)?'✓ In plan':'+ Add to my plan'}</button></div>`,'Event details · '+src.short)}
function profileModal(){draftInterests=[...state.interests];show('A campus experience that fits you.',`<form id="profile-form"><p class="lead">Choose interests and what you can share. This profile stays in your browser and is never published.</p><div class="modal-grid"><div class="field"><label for="profile-field">Field of study</label>${select('profile-field','Field of study',Object.keys(D.fields).map(f=>[f,f]),state.field)}</div><div class="field"><label for="profile-role">Audience</label>${select('profile-role','Audience',[['undergraduate','Undergraduate student'],['graduate','Graduate student'],['instructor','Instructor / teaching assistant'],['all','Show all audiences']],state.role)}</div><div class="field full"><label for="profile-goal">Your current goal</label>${select('profile-goal','Your goal',Object.entries(D.goals),state.goal)}</div></div><label class="tiny">Your interests</label><div class="modal-chips" id="profile-interests">${D.topics.map(t=>`<button type="button" data-interest="${t}" class="${draftInterests.includes(t)?'selected':''}" aria-pressed="${draftInterests.includes(t)}">${t}</button>`).join('')}</div><div class="modal-grid"><div class="field"><label for="profile-offer">A skill or perspective you can share</label>${select('profile-offer','Skill you offer',[...new Set([...D.topics,'Data'])].map(t=>[t,t]),state.offer)}</div><div class="field"><label for="profile-seek">Something you would like to learn</label>${select('profile-seek','Skill you seek',[...new Set([...D.topics,'Data'])].map(t=>[t,t]),state.seek)}</div></div><div class="modal-bottom"><button class="button primary" type="submit">Save my preferences</button></div></form>`,'Make it yours')}
function addToPlan(id){if(state.plan.includes(id)){toast('Already in your plan. Open My campus plan to review it.');return}const e=event(id);if(!e)return;const overlap=state.plan.map(event).filter(Boolean).some(x=>E.conflicts(x,e,state.buffer));state.plan.push(id);persist();render();toast(overlap?'Added with a schedule conflict. Review My campus plan.':'Added to your plan. This is not an RSVP.');if($('#modal').open)details(id)}
function introduction(id){const p=D.people.find(p=>p.id===id);if(!p)return;const m=personMatch(p),ev=event(m.shared[0]||p.events[0]);const draft=`Hi ${p.name.split(' ')[0]}! I’m interested in ${ev.title}. I’m exploring ${state.seek.toLowerCase()} and noticed you can share ${p.offer.toLowerCase()}. I can bring ${state.offer.toLowerCase()}—would you be open to comparing ideas at the event?`;show('Start with something in common.',`<p class="tiny">For ${p.name} · Fictional profile · Template-based draft</p><div class="quote">${esc(draft)}</div><p class="lead">Edit the wording to sound like you. This prepares an introduction; it does not contact anyone.</p><div class="field"><label for="intro-draft">Your editable introduction</label><textarea id="intro-draft" rows="4">${esc(draft)}</textarea></div><div class="modal-bottom"><button class="button" data-action="copy-intro">Copy text</button><button class="button primary" data-shortlist="${p.id}">${state.shortlist.includes(id)?'✓ Shortlisted':'+ Save person for later'}</button></div>`,'An introduction with a reason')}
function note(id){const e=event(id);if(!e)return;show('Keep the connection going.',`<form id="note-form" data-id="${esc(id)}"><p class="lead">${esc(e.title)}</p><p class="tiny">A private reflection in this browser. Avoid adding someone else’s contact details without their permission.</p><div class="field"><label for="reflection">What did you learn, and what is your next step?</label><textarea id="reflection" maxlength="2000" rows="5" placeholder="One idea to explore, someone to follow up with, or a project to try…">${esc(state.notes[id]||'')}</textarea></div><div class="modal-bottom"><button class="button primary" type="submit">Save reflection</button></div></form>`,'After the event')}
function model(){const query=filters.query||'Build an app with a designer',r=E.classify(query);show('Small AI. Clear explanations.',`<p class="lead">A multinomial Naive Bayes text classifier learns from 72 synthetic example goals across six intents. It runs in this browser without an API call or account.</p><div class="field"><label for="model-query">Try your own sentence</label><input id="model-query" maxlength="250" value="${esc(query)}"></div><button class="button primary" style="margin-top:12px" data-action="test-model">Classify intent</button><div id="model-result" class="reason" aria-live="polite">${r.length?'Predicted focus: '+esc(D.goals[r[0].label]):'No recognized training vocabulary. Try a more specific goal.'}</div><p class="tiny">The classifier supplies an intent signal. Ranking then combines that signal with interests, exact text overlap, and an optional bonus for unfamiliar disciplines. No accuracy or calibrated confidence is claimed; unfamiliar language can be misclassified.</p><p class="tiny">The planner, peer suggestions, duplicate checks, and event-text extraction are rule-based. They are not language-model outputs.</p>`,'How AI is used')}
function privacy(){show('Your data stays with you.',`<p>OwlCircle stores preferences, plans, bookmarks, local event imports, shortlists, and reflections in this browser only. They are not shared with other visitors.</p><p>We do not request a name, email, student ID, login, or calendar access. The demo contains no real student profiles and sends no messages. The local intent model does not transmit your typed goals.</p><p>Opening a source link takes you to that provider’s website, where its privacy policies apply. In a production pilot, organizers would need to approve data access, and students would opt in before sharing any profile or attendance.</p><div class="modal-bottom"><button class="button" data-action="confirm-reset">Clear my local data</button><button class="button primary" data-action="close">Done</button></div>`,'Data and privacy')}
function importModal(example=false){show('Bring an event into one place.',`<p class="lead">Paste public event text. Review the extracted fields before saving a local copy. No page is fetched and nothing is published.</p><div class="field"><label for="import-text">Event text</label><textarea id="import-text" rows="7" placeholder="Title: Campus workshop\nDate: 2026-11-13\nStart: 15:00\nEnd: 16:00\nLocation: Online\nURL: https://…\nDescription: …">${example?'Title: Build for good: campus idea lab\nDate: 2026-11-09\nStart: 17:00\nEnd: 18:30\nLocation: Charles Library · collaboration room\nURL: https://library.temple.edu/events\nDescription: A fictional duplicate for testing the import workflow.':''}</textarea></div><div class="modal-bottom"><button class="button" data-action="duplicate-demo">Load duplicate example</button><button class="button primary" data-action="extract-event">Extract and review</button></div>`,'Manual import · Rule-based extraction')}
function reviewImport(){const f=E.extract($('#import-text').value);show('Review before adding.',`<form id="import-form"><p class="tiny">These fields were extracted with simple text rules. Correct every field. The entry will be labeled local and unverified.</p><div class="modal-grid"><div class="field full"><label for="imp-title">Title</label><input id="imp-title" value="${esc(f.title)}" required maxlength="160"></div><div class="field"><label for="imp-date">Date</label><input id="imp-date" type="date" value="${esc(f.date)}" min="2026-11-01" max="2026-11-30" required></div><div class="field"><label for="imp-format">Format</label>${select('imp-format','Format',[['In person','In person'],['Online','Online']],/online|zoom/i.test(f.location||'')?'Online':'In person')}</div><div class="field"><label for="imp-start">Start time ET</label><input id="imp-start" type="time" value="${esc(f.start)}" required></div><div class="field"><label for="imp-end">End time ET</label><input id="imp-end" type="time" value="${esc(f.end)}" required></div><div class="field full"><label for="imp-place">Location</label><input id="imp-place" value="${esc(f.location)}" maxlength="200" required></div><div class="field full"><label for="imp-url">Original source URL</label><input id="imp-url" type="url" value="${esc(f.url)}" required maxlength="2000"></div><div class="field"><label for="imp-topic">Topic</label>${select('imp-topic','Topic',D.topics.map(t=>[t,t]),'Community')}</div><div class="field"><label for="imp-goal">Relevant goal</label>${select('imp-goal','Relevant goal',Object.entries(D.goals),'connect')}</div><div class="field full"><label for="imp-description">Short description</label><textarea id="imp-description" maxlength="1000">${esc(f.description)}</textarea></div></div><div id="import-error" class="form-error" role="alert"></div><div class="modal-bottom"><button type="button" class="button" data-action="import">Back</button><button class="button primary" type="submit">Check duplicates & save</button></div></form>`,'Review an import')}
function tour(){const steps=[{title:'Start with a goal, not a platform.',art:'“I want to build an app with a designer.”',body:'The local AI classifier recognizes a building goal. OwlCircle ranks opportunities across library workshops, business events, and campus communities.',action:'tour-discover',cta:'Try goal-based discovery'},{title:'Turn the possibilities into a plan.',art:'3 hours. Up to 3 events. A wider campus.',body:'Set a weekly time budget and include public listings or demo events. The planner balances relevance and variety while avoiding overlapping sessions.',action:'tour-plan',cta:'Try the campus planner'},{title:'Find complementary strengths.',art:'You bring technology.<br>They bring design.',body:'See why a fictional peer might be a good match, find a shared event, and prepare an introduction. No message is sent.',action:'tour-people',cta:'Explore sample peers'},{title:'Know where every listing came from.',art:'One event. Original sources. Clear provenance.',body:'Inspect public snapshots, distinguish simulated records, and see a real cross-listing discrepancy. Try importing a duplicate and watch the check catch it.',action:'tour-sources',cta:'Inspect connected sources'}];const s=steps[tourStep];show(s.title,`<div class="tour-progress">${steps.map((_,i)=>`<i class="${i===tourStep?'active':''}"></i>`).join('')}</div><div class="tour-art">${s.art}</div><p class="lead">${s.body}</p><div class="modal-bottom">${tourStep?'<button class="button" data-action="tour-prev">Previous</button>':''}<button class="button primary" data-action="${s.action}">${s.cta} ↗</button><button class="button" data-action="${tourStep===3?'close':'tour-next'}">${tourStep===3?'Finish':'Next'}</button></div>`,'60-second tour · '+(tourStep+1)+' of 4')}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const actions={
profile:profileModal,close,privacy,model,'reset-resources':()=>{resourceQuery='';resourceCategory='all';render()},import:()=>importModal(), 'duplicate-demo':()=>importModal(true),'extract-event':reviewImport,
'tour':()=>{tourStep=0;tour()},'tour-next':()=>{tourStep=Math.min(3,tourStep+1);tour()},'tour-prev':()=>{tourStep=Math.max(0,tourStep-1);tour()},
'tour-discover':()=>{filters.query='Build an app with a designer';close();navigate('discover')},'tour-plan':()=>{close();navigate('plan')},'tour-people':()=>{close();navigate('people')},'tour-sources':()=>{close();navigate('sources')},
'clear-query':()=>{filters.query='';render()},'clear-filters':()=>{filters={query:'',source:'all',kind:'all',category:'all',format:'all',day:'all',sort:'match'};render()},
'suggest-plan':()=>{let pool=allEvents().filter(e=>eligible(e)&&(state.planMode==='all'||(state.planMode==='saved'?state.saved.includes(e.id):e.status===state.planMode))&&(!state.planFree||e.price===0)&&(state.planTime==='any'||E.mins(e.start)>=(state.planTime==='evening'?960:720)));const suggested=E.recommendPlan(pool,profile(),{budget:state.budget,buffer:state.buffer,query:filters.query});if(!suggested.length){toast('No events fit those constraints. Try more time or another listing type.');return}state.plan=suggested.map(e=>e.id);persist();render();toast('A varied plan is ready. Review source details before attending.')},
export:()=>{const list=state.plan.map(event).filter(Boolean);if(!list.length)return;download('OwlCircle_Campus_Plan.ics',E.ics(list),'text/calendar;charset=utf-8');toast('Calendar downloaded. Demo events are labeled [DEMO].')},
'copy-intro':async()=>{try{await navigator.clipboard.writeText($('#intro-draft').value);toast('Introduction copied. Nothing was sent.')}catch{$('#intro-draft').focus();$('#intro-draft').select();toast('Select and copy the text from the introduction box.')}},
'confirm-reset':()=>show('Clear this browser’s OwlCircle data?',`<p>This removes your saved events, plan, imported entries, shortlists, and reflections from this browser. The sample dataset stays available.</p><div class="modal-bottom"><button class="button" data-action="close">Keep my data</button><button class="button primary" data-action="reset">Clear my local data</button></div>`,'Reset local preferences'),
reset:()=>{state=initial();persist();close();filters={query:'',source:'all',kind:'all',category:'all',format:'all',day:'all',sort:'match'};peopleFilter='all';navigate('discover');toast('Local data cleared. Demo defaults restored.')},
 'test-model':()=>{const r=E.classify($('#model-query').value);$('#model-result').textContent=r.length?'Predicted focus: '+D.goals[r[0].label]+' · Also considered: '+D.goals[r[1].label]:'No recognized training vocabulary. Try a more specific goal.'}
};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav){navigate(b.dataset.nav);return}if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.event){details(b.dataset.event);return}if(b.dataset.prompt){filters.query=b.dataset.prompt;render();return}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'Saved to your possibilities.':'Removed from saved events.');if($('#modal').open)details(id);return}if(b.dataset.plan){addToPlan(b.dataset.plan);return}if(b.dataset.removePlan){state.plan=state.plan.filter(id=>id!==b.dataset.removePlan);persist();render();return}if(b.dataset.peopleEvent){peopleFilter=b.dataset.peopleEvent;navigate('people');return}if(b.dataset.intro){introduction(b.dataset.intro);return}if(b.dataset.note){note(b.dataset.note);return}if(b.dataset.shortlist){const id=b.dataset.shortlist;state.shortlist=state.shortlist.includes(id)?state.shortlist.filter(x=>x!==id):[...state.shortlist,id];persist();render();toast('Local shortlist updated. No request was sent.');if($('#modal').open)introduction(id);return}if(b.dataset.sourceFilter){filters={query:'',source:b.dataset.sourceFilter,category:'all',kind:'all',day:'all',format:'all',sort:'match'};navigate('discover');return}if(b.dataset.interest){const t=b.dataset.interest;draftInterests=draftInterests.includes(t)?draftInterests.filter(x=>x!==t):[...draftInterests,t];b.classList.toggle('selected',draftInterests.includes(t));b.setAttribute('aria-pressed',String(draftInterests.includes(t)))}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='resource-category'){resourceCategory=t.value;render()}if(t.id.startsWith('filter-')){filters[t.id.slice(7)]=t.value;render()}if(t.id==='diversify'){state.diverse=t.checked;persist();render()}if(t.id==='people-filter'){peopleFilter=t.value;render()}if(t.id==='visibility'){state.visibility=t.checked;persist();render()}if(t.id==='plan-budget'){state.budget=Number(t.value);persist();render()}if(t.id==='plan-mode'){state.planMode=t.value;persist()}if(t.id==='plan-time'){state.planTime=t.value;persist()}if(t.id==='plan-free'){state.planFree=t.checked;persist()}});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(f.id==='resource-form'){resourceQuery=$('#resource-query').value.trim();render()}if(f.id==='goal-form'){filters.query=$('#goal-query').value.trim();render()}if(f.id==='profile-form'){state.field=$('#profile-field').value;state.role=$('#profile-role').value;state.goal=$('#profile-goal').value;state.interests=draftInterests;state.offer=$('#profile-offer').value;state.seek=$('#profile-seek').value;persist();close();render();toast('Your recommendations have been updated.')}if(f.id==='note-form'){state.notes[f.dataset.id]=$('#reflection').value.trim();persist();close();render();toast('Reflection saved only in this browser.')}if(f.id==='import-form'){const title=$('#imp-title').value.trim(),date=$('#imp-date').value,start=$('#imp-start').value,end=$('#imp-end').value,url=$('#imp-url').value.trim(),place=$('#imp-place').value.trim();if(!title||!place||!date||!start||!end||E.mins(end)<=E.mins(start)||!E.validURL(url)){$('#import-error').textContent='Enter a title, location, valid date, end time after start, and an http or https source URL.';return}const item={id:'local-'+Date.now(),title,date,start,end,url,place,format:$('#imp-format').value,description:$('#imp-description').value.trim(),topics:[$('#imp-topic').value],category:$('#imp-topic').value,goals:[$('#imp-goal').value],source:'local',sources:['local'],status:'local',price:null,audience:'Not verified',access:'Not verified. Contact the organizer.',beginner:false};const dupe=allEvents().find(e=>E.duplicate(e,item));if(dupe){show('This event is already in your circle.',`<p>We found an event with the same normalized title, date, and start time. A second card was not added.</p><div class="reason">${esc(dupe.title)}<br>${shortDate(dupe.date)} · ${range(dupe)}</div><p class="tiny">This is a conservative exact-match check. Similar titles, rescheduled events, or different formatting may still need human review. New source metadata is not merged automatically.</p><button class="button primary" data-event="${esc(dupe.id)}">Review existing event ↗</button>`,'Duplicate detected');return}state.local.push(item);persist();close();filters={kind:'local',source:'all',category:'all',query:'',day:'all',format:'all',sort:'match'};navigate('discover');toast('Added locally as unverified. No data was published.')}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['discover','plan','people','sources','about'].includes(next)){view=next;render()}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
render();
